let bookingProgress=loadJSON(STORAGE_KEY,{});
function loadJSON(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v&&typeof v==='object'?v:fallback}catch(e){return fallback}}
function saveJSON(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch(e){}}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function outOfChina(lat,lng){return lng<72.004||lng>137.8347||lat<0.8293||lat>55.8271}
function transformLat(x,y){let r=-100+2*x+3*y+.2*y*y+.1*x*y+.2*Math.sqrt(Math.abs(x));r+=(20*Math.sin(6*x*Math.PI)+20*Math.sin(2*x*Math.PI))*2/3;r+=(20*Math.sin(y*Math.PI)+40*Math.sin(y/3*Math.PI))*2/3;r+=(160*Math.sin(y/12*Math.PI)+320*Math.sin(y*Math.PI/30))*2/3;return r}
function transformLng(x,y){let r=300+x+2*y+.1*x*x+.1*x*y+.1*Math.sqrt(Math.abs(x));r+=(20*Math.sin(6*x*Math.PI)+20*Math.sin(2*x*Math.PI))*2/3;r+=(20*Math.sin(x*Math.PI)+40*Math.sin(x/3*Math.PI))*2/3;r+=(150*Math.sin(x/12*Math.PI)+300*Math.sin(x/30*Math.PI))*2/3;return r}
function wgs84ToGcj02(lat,lng){if(outOfChina(lat,lng))return[lat,lng];const a=6378245,ee=.00669342162296594323,dLat=transformLat(lng-105,lat-35),dLng=transformLng(lng-105,lat-35),rad=lat/180*Math.PI,magic=1-ee*Math.sin(rad)*Math.sin(rad),sqrt=Math.sqrt(magic);return[lat+(dLat*180)/((a*(1-ee))/(magic*sqrt)*Math.PI),lng+(dLng*180)/(a/sqrt*Math.cos(rad)*Math.PI)]}
function pointById(id){return POINTS.find(p=>p.id===id)}
function bookingById(id){return BOOKINGS.find(b=>b.id===id)}
function routePoints(schedule){return schedule.route.map(pointById).filter(Boolean)}
function shortName(name){return String(name).replace(/^推荐住宿核心区：/,'').replace(/地铁站$/,'站').replace(/海水浴场$/,'浴场').replace(/景区.*$/,'景区')}
function pointIcon(id){return POINT_ICONS[id]||'•'}
function bookingItemsForPoint(id){return BOOKINGS.filter(b=>b.pointIds.includes(id))}
function bookingItemsForDay(date){return BOOKINGS.filter(b=>b.dates.includes(date))}
function bookingLevelRank(level){return level==='required'?2:level==='suggested'?1:0}
function activeBookingItems(items){return items.filter(b=>progressValue(b.id)!=='abandoned')}
function pointBookingLevel(id){return activeBookingItems(bookingItemsForPoint(id)).reduce((a,b)=>bookingLevelRank(b.level)>bookingLevelRank(a)?b.level:a,'none')}
function dayBookingLevel(date){return activeBookingItems(bookingItemsForDay(date)).reduce((a,b)=>bookingLevelRank(b.level)>bookingLevelRank(a)?b.level:a,'none')}
function progressValue(id){return bookingProgress[id]||'pending'}
function dateLabel(dates){return dates.map(d=>`8月${Number(d.slice(3))}日`).join(' / ')}
function dotHtml(level,id=''){if(level==='none')return'';if(id&&progressValue(id)==='abandoned')return'';const done=id&&['booked','checked'].includes(progressValue(id));return `<span class="booking-dot ${level} ${done?'done':''}" title="${level==='required'?'必须预约/购票':'建议提前'}"></span>`}
function progressSelectHtml(item){const v=progressValue(item.id);return `<select class="booking-progress" data-booking-progress="${item.id}" aria-label="${escapeHtml(item.name)}处理状态"><option value="pending" ${v==='pending'?'selected':''}>未处理</option><option value="booked" ${v==='booked'?'selected':''}>已预约/购票</option><option value="checked" ${v==='checked'?'selected':''}>已核验</option><option value="abandoned" ${v==='abandoned'?'selected':''}>放弃</option></select>`}
function channelButtonsHtml(item){return item.channels.map((c,i)=>`<button class="booking-channel" data-booking-channel="${item.id}" data-channel-index="${i}">${escapeHtml(c.label)}</button>`).join('')}
function bookingItemHtml(item,compact=false){const v=progressValue(item.id),done=['booked','checked'].includes(v),abandoned=v==='abandoned';return `<div class="booking-item ${done?'done':''} ${abandoned?'abandoned':''}"><div class="booking-item-head">${dotHtml(item.level,item.id)}<div class="booking-item-main"><div class="booking-item-title">${escapeHtml(item.name)}${item.optional?'<span class="booking-optional">备选启用后</span>':''}${abandoned?'<span class="booking-abandoned-tag">已放弃</span>':''}</div><div class="booking-item-meta">${dateLabel(item.dates)} · ${abandoned?'不再提醒':item.level==='required'?'必须预约/购票':'建议提前处理'}</div></div></div>${compact?'':`<div class="booking-item-note">${escapeHtml(item.note)}</div>`}<div class="booking-controls">${channelButtonsHtml(item)}${progressSelectHtml(item)}</div></div>`}
function renderBookingChecklist(){const box=document.getElementById('bookingChecklist');const sorted=[...BOOKINGS].sort((a,b)=>bookingLevelRank(b.level)-bookingLevelRank(a.level)||a.dates[0].localeCompare(b.dates[0]));box.innerHTML=`<div class="booking-list">${sorted.map(x=>bookingItemHtml(x)).join('')}</div>`}
function showGuide(message){const box=document.getElementById('guideToast');box.innerHTML=`${escapeHtml(message)}<br><button type="button" id="closeGuide">知道了</button>`;box.classList.add('show');document.getElementById('closeGuide').onclick=()=>box.classList.remove('show');setTimeout(()=>box.classList.remove('show'),6000)}
function platformUrl(kind,keyword){const q=encodeURIComponent(keyword);if(kind==='meituan')return`https://www.meituan.com/s/${q}/`;if(kind==='douyin')return`https://www.douyin.com/search/${q}?type=general`;if(kind==='xhs')return`https://www.xiaohongshu.com/search_result?keyword=${q}`;if(kind==='dianping')return`https://m.dianping.com/search?keyword=${q}`;return''}
function openBookingChannel(id,index){const item=bookingById(id),c=item&&item.channels[index];if(!c)return;if(c.kind==='url'){window.open(c.url,'_blank','noopener');return}if(c.kind==='wechat'){showGuide(`请在微信搜索“${c.keyword}”，从官方公众号/小程序进入。手机将尝试打开微信。`);if(/Android|iPhone|iPad|iPod/i.test(navigator.userAgent))setTimeout(()=>{location.href='weixin://'},150);return}const url=platformUrl(c.kind,c.keyword);if(url)window.open(url,'_blank','noopener')}
function setBookingProgress(id,value){bookingProgress[id]=value;saveJSON(STORAGE_KEY,bookingProgress);refreshLinkedViews()}
function iconFor(p){return L.divIcon({className:'',html:travelMarkerHtml(p),iconSize:[160,32],iconAnchor:[15,16],popupAnchor:[58,-10]})} function amapLinks(p){const [glat,glng]=wgs84ToGcj02(p.lat,p.lng),name=encodeURIComponent(p.name);return{search:`https://uri.amap.com/search?keyword=${name}&city=%E9%9D%92%E5%B2%9B&view=map&src=travel-plans`,glat,glng}}
function launchAmap(id){const p=pointById(id);if(!p)return;const a=amapLinks(p),ua=navigator.userAgent,name=encodeURIComponent(p.name),source=encodeURIComponent('travel-plans');const isIOS=/iPhone|iPad|iPod/i.test(ua),isAndroid=/Android/i.test(ua);if(!isIOS&&!isAndroid){window.open(a.search,'_blank','noopener');return}const appUrl=isIOS?`iosamap://path?sourceApplication=${source}&dlat=${a.glat.toFixed(6)}&dlon=${a.glng.toFixed(6)}&dname=${name}&dev=0&t=0`:`amapuri://route/plan/?sourceApplication=${source}&dlat=${a.glat.toFixed(6)}&dlon=${a.glng.toFixed(6)}&dname=${name}&dev=0&t=0`;let hidden=false;document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')hidden=true},{once:true});location.href=appUrl;setTimeout(()=>{if(!hidden&&document.visibilityState==='visible')location.href=a.search},1800)}
window.launchAmap=launchAmap;
function popup(p){const a=amapLinks(p),bookings=bookingItemsForPoint(p.id);const sourceLinks=`${p.sourceUrl?`<a href="${p.sourceUrl}" target="_blank" rel="noopener">${escapeHtml(p.source)}</a>`:escapeHtml(p.source)}${p.mapUrl?` · <a href="${p.mapUrl}" target="_blank" rel="noopener">坐标核验页</a>`:''}`;return `<div class="pop"><h3>${pointIcon(p.id)} ${escapeHtml(p.name)}</h3><div class="meta">${escapeHtml(p.category)} · ${escapeHtml(p.status)} · ${escapeHtml(p.time)}</div><p>${escapeHtml(p.detail)}</p><p><b>交通：</b>${escapeHtml(p.transport)}</p><p><b>提醒：</b>${escapeHtml(p.tips)}</p>${bookings.length?`<p><b>预约：</b>${bookings.map(b=>b.level==='required'?'必须处理':'建议提前').join('；')}</p>`:''}<p><b>来源：</b>${sourceLinks}</p><div class="coord">WGS84 ${p.lat.toFixed(6)}, ${p.lng.toFixed(6)}<br>GCJ-02 ${a.glat.toFixed(6)}, ${a.glng.toFixed(6)}</div><div class="pop-actions"><button onclick="launchAmap('${p.id}')">打开高德App</button><a class="alt" href="${a.search}" target="_blank" rel="noopener">网页搜索备用</a></div></div>`}
function markerGroup(){return typeof L.markerClusterGroup==='function'?L.markerClusterGroup({showCoverageOnHover:false,maxClusterRadius:38,spiderfyOnMaxZoom:true}):L.layerGroup()}
function visiblePoints(day=null){if(recommendationMode)return POINTS.filter(p=>RECOMMENDED.includes(p.id));if(day)return POINTS.filter(p=>(p.days||[]).includes(day)||['酒店','住宿区域'].includes(p.category));return POINTS.filter(p=>p.category!=='推荐')}
function rebuildMarkers(day=null){selectedDay=day;if(!clusters)return;clusters.clearLayers();visiblePoints(day).forEach(p=>{const m=markers.get(p.id);if(m)clusters.addLayer(m)})}
function routeOrderMap(schedule){const map=new Map();schedule.route.forEach((id,i)=>{if(!map.has(id))map.set(id,[]);map.get(id).push(i+1)});return map}
function routeMarkerIcon(color,label,p){return L.divIcon({className:'',html:travelRouteMarkerHtml(color,label,p),iconSize:[170,34],iconAnchor:[15,17],popupAnchor:[60,-10]})} function bearingRotation(a,b){return Math.atan2(b.lat-a.lat,b.lng-a.lng)*180/Math.PI}
function directionIcon(color,rotation){return L.divIcon({className:'',html:travelDirectionHtml(color,rotation),iconSize:[28,28],iconAnchor:[14,14]})} function setDayRouteCard(d){const box=document.getElementById('dayRouteCard');if(!d){box.classList.remove('show');box.innerHTML='';renderLegend(SCHEDULES[1]?.date);return}const ps=routePoints(d);box.innerHTML=`<div class="day-route-head"><div><b>8月${Number(d.date.slice(3))}日｜${escapeHtml(d.title)}</b><div class="route-day-weather">${escapeHtml(tripWeatherCompact(d.date))}</div><div class="day-route-note">高亮线路只表示游览先后，不替代道路导航</div></div><button class="day-route-close" type="button">×</button></div><div class="day-route-seq">${ps.map((p,i)=>`<button data-route-point="${p.id}"><span style="background:${d.color}">${i+1}</span>${pointIcon(p.id)} ${escapeHtml(shortName(p.name))}</button>`).join('<i>→</i>')}</div>`;box.classList.add('show');box.querySelector('.day-route-close').onclick=showAll;box.querySelectorAll('[data-route-point]').forEach(b=>b.onclick=()=>focusPoint(b.dataset.routePoint));renderLegend(d.date)} function drawRoutes(day=null){if(!routeLayer)return;routeLayer.clearLayers();if(!routeVisible||recommendationMode){setDayRouteCard(null);return}if(!day){setDayRouteCard(null);SCHEDULES.forEach(d=>{const ps=routePoints(d);if(ps.length<2)return;L.polyline(ps.map(p=>[p.lat,p.lng]),{color:'#fff',weight:5,opacity:.65,lineJoin:'round',interactive:false}).addTo(routeLayer);L.polyline(ps.map(p=>[p.lat,p.lng]),{color:d.color,weight:2.5,opacity:.58,dashArray:'5 8',lineJoin:'round'}).bindTooltip(`8/${d.date.slice(3)} ${d.title}<br>总览仅显示线路范围`).addTo(routeLayer)});return}const d=SCHEDULES.find(x=>x.date===day);if(!d)return;const ps=routePoints(d),order=routeOrderMap(d);setDayRouteCard(d);if(ps.length<2)return;const coords=ps.map(p=>[p.lat,p.lng]);L.polyline(coords,{color:'#fff',weight:11,opacity:.94,lineCap:'round',lineJoin:'round',interactive:false}).addTo(routeLayer);L.polyline(coords,{color:d.color,weight:6,opacity:1,lineCap:'round',lineJoin:'round'}).addTo(routeLayer);order.forEach((nums,id)=>{const p=pointById(id);if(p)L.marker([p.lat,p.lng],{icon:routeMarkerIcon(d.color,nums.join('/'),p),zIndexOffset:700}).bindPopup(popup(p),{maxWidth:360}).addTo(routeLayer)});for(let i=0;i<ps.length-1;i++){const a=ps[i],b=ps[i+1];if(a.lat===b.lat&&a.lng===b.lng)continue;const count=map&&map.distance([a.lat,a.lng],[b.lat,b.lng])>18000?2:1;for(let k=1;k<=count;k++){const ratio=count===1?.5:k/(count+1),lat=a.lat+(b.lat-a.lat)*ratio,lng=a.lng+(b.lng-a.lng)*ratio;L.marker([lat,lng],{icon:directionIcon(d.color,bearingRotation(a,b)),interactive:false,zIndexOffset:500}).addTo(routeLayer)}}}
function fitPoints(ps,maxZoom=13){if(!map||!ps||!ps.length)return;map.fitBounds(L.latLngBounds(ps.map(p=>[p.lat,p.lng])).pad(.25),{maxZoom})}
function closePanelOnMobile(){if(innerWidth<=800)setPanelCollapsed(true)}
function filterDay(day){const d=SCHEDULES.find(x=>x.date===day);if(!d)return;recommendationMode=false;routeVisible=true;rebuildMarkers(day);drawRoutes(day);if(mapEngine==='amap')syncAmapView();else fitPoints(routePoints(d),13);document.querySelectorAll('.day-card').forEach(el=>el.classList.toggle('active',el.dataset.day===day));activateTab('days',true);closePanelOnMobile();setTimeout(()=>{if(mapEngine==='amap')syncAmapView();else if(map){map.invalidateSize();fitPoints(routePoints(d),13)}},260)}
function showAll(){recommendationMode=false;selectedDay=null;routeVisible=true;rebuildMarkers(null);drawRoutes(null);if(mapEngine==='amap')syncAmapView();else fitPoints(POINTS.filter(p=>p.category!=='行程节点'&&p.category!=='推荐'),11);document.querySelectorAll('.day-card').forEach(el=>el.classList.remove('active'))}
function clearRoutes(){routeVisible=false;if(routeLayer)routeLayer.clearLayers();setDayRouteCard(null);syncAmapView()}
function dayBookingsHtml(d){const items=bookingItemsForDay(d.date);return items.length?`<div class="day-bookings"><div class="day-bookings-title">预约 / 购票</div><div class="booking-list">${items.map(x=>bookingItemHtml(x)).join('')}</div></div>`:''}
function renderDays(){const open=new Set([...document.querySelectorAll('.day-card[open]')].map(x=>x.dataset.day));document.getElementById('days').innerHTML=SCHEDULES.map((d,i)=>{const level=dayBookingLevel(d.date);return `<details class="day-card" data-day="${d.date}" ${open.has(d.date)||(!open.size&&i===1)?'open':''}><summary><span class="day-dot" style="background:${d.color}"></span><div class="day-summary-layout"><div><button class="day-title-button" type="button" data-day-focus="${d.date}">8月${Number(d.date.slice(3))}日｜${escapeHtml(d.title)}</button><div class="day-summary">${escapeHtml(d.summary)}</div></div></div><div class="day-summary-right"><span class="day-weather-chip">${escapeHtml(tripWeatherCompact(d.date))}</span>${dotHtml(level)}<span class="day-action">展开</span></div></summary><div class="day-body">${tripWeatherDetailHtml(d.date)}<div class="timeline">${d.items.map(x=>`<div class="t">${escapeHtml(x[0])}</div><div>${escapeHtml(x[1])}</div>`).join('')}</div>${dayBookingsHtml(d)}<div class="planb"><b>Plan B：</b>${escapeHtml(d.planB)}</div></div></details>`}).join('');document.querySelectorAll('[data-day-focus]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();filterDay(b.dataset.dayFocus)}))} function renderSources(){document.getElementById('sources').innerHTML=SOURCES.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${escapeHtml(s.name)}</a><span>${escapeHtml(s.note)}</span></li>`).join('')}
function renderHotels(){document.getElementById('hotelRows').innerHTML=HOTELS.map(r=>`<tr>${r.map(x=>`<td>${escapeHtml(x)}</td>`).join('')}</tr>`).join('')}
function renderLegend(focusDate=selectedDay||SCHEDULES[1]?.date){const box=document.getElementById('legend'),state=loadJSON(LEGEND_STATE_KEY,{collapsed:false});box.classList.toggle('collapsed',Boolean(state.collapsed));box.innerHTML=`<div class="legend-head"><b>每日路线总览</b><button type="button" id="legendToggle">${state.collapsed?'展开':'收起'}</button></div>${tripLegendWeatherHtml(focusDate||SCHEDULES[1].date)}<div class="legend-body">${SCHEDULES.slice(1,8).map(d=>`<div class="legend-row"><span class="legend-route-name"><span class="sw" style="border-color:${d.color}"></span><span>8/${d.date.slice(3)} ${escapeHtml(d.title.split('＋')[0])}</span></span><span class="legend-weather">${escapeHtml(tripWeatherCompact(d.date))}</span></div>`).join('')}<div class="overview-line-note">点击某日标题后显示方向、序号与当日天气</div></div>`;const button=document.getElementById('legendToggle');if(button)button.onclick=()=>{const collapsed=!box.classList.contains('collapsed');box.classList.toggle('collapsed',collapsed);saveJSON(LEGEND_STATE_KEY,{collapsed});button.textContent=collapsed?'展开':'收起'}} function presetPointIds(){return [...REQUIRED,...OPTIONAL]}
function normalizePresetOrder(){const saved=loadJSON(ORDER_KEY,[]),ids=presetPointIds();presetOrder=[...saved.filter(id=>ids.includes(id)),...ids.filter(id=>!saved.includes(id))]}
function renderPresetDestinations(){const select=document.getElementById('presetDestination');select.innerHTML=`<option value="">请选择目的地</option><optgroup label="必去目的地">${REQUIRED.map(id=>pointById(id)).filter(Boolean).map(p=>`<option value="${p.id}">${escapeHtml(shortName(p.name))}</option>`).join('')}</optgroup><optgroup label="室内备选">${OPTIONAL.map(id=>pointById(id)).filter(Boolean).map(p=>`<option value="${p.id}">${escapeHtml(shortName(p.name))}</option>`).join('')}</optgroup>`;select.value=selectedPresetId;renderPresetCards()}
function pointBookingsSection(p){const items=bookingItemsForPoint(p.id);return items.length?`<div class="search-bookings"><div class="day-bookings-title">预约 / 购票</div>${items.map(x=>bookingItemHtml(x)).join('')}</div>`:''}
function destinationNoticeHtml(p){return `<div class="destination-notice" aria-live="polite"><div class="destination-notice-title">注意事项</div><h3>${pointIcon(p.id)} ${escapeHtml(p.name)}</h3><div class="meta">${escapeHtml(p.category)} · ${escapeHtml(p.status)} · ${escapeHtml(p.time)}</div><p><b>目的地说明：</b>${escapeHtml(p.detail)}</p><p><b>交通：</b>${escapeHtml(p.transport)}</p><p><b>现场提醒：</b>${escapeHtml(p.tips)}</p>${pointBookingsSection(p)}<div class="notice-actions"><button class="btn primary notice-focus" data-id="${p.id}">地图定位</button><button class="btn notice-amap" data-id="${p.id}">打开高德App</button></div></div>`}
function renderPresetCards(){const box=document.getElementById('presetCards');box.innerHTML=presetOrder.map(id=>{const p=pointById(id),level=pointBookingLevel(id),selected=id===selectedPresetId;return `<div class="preset-card-wrap ${selected?'selected':''}"><button type="button" class="preset-card ${selected?'active':''}" data-preset-id="${id}"><span class="preset-icon">${pointIcon(id)}</span><span class="preset-card-main"><span class="preset-card-name">${escapeHtml(shortName(p.name))}</span><span class="preset-card-sub">${escapeHtml(p.status)}</span></span>${dotHtml(level)}</button>${selected?destinationNoticeHtml(p):''}</div>`}).join('');box.querySelectorAll('[data-preset-id]').forEach(b=>b.onclick=()=>selectPresetDestination(b.dataset.presetId,{promote:false,from:'card'}));box.querySelectorAll('.notice-focus').forEach(b=>b.onclick=()=>focusPoint(b.dataset.id));box.querySelectorAll('.notice-amap').forEach(b=>b.onclick=()=>launchAmap(b.dataset.id))}
function selectPresetDestination(id,{promote=true,from='dropdown'}={}){const p=pointById(id);selectedPresetId=id;document.getElementById('presetDestination').value=id;if(!p){renderPresetCards();return}if(promote){presetOrder=[id,...presetOrder.filter(x=>x!==id)];saveJSON(ORDER_KEY,presetOrder)}renderPresetCards();document.getElementById('searchInput').value=p.name;currentSearchIds=[id];renderSearchResults([p]);focusPoint(id)}
function renderSearchResults(hits){currentSearchIds=hits.map(p=>p.id);const box=document.getElementById('searchResults');box.innerHTML=hits.length?hits.map(p=>{const level=pointBookingLevel(p.id);return `<div class="search-card"><div class="search-card-head"><div><h4>${pointIcon(p.id)} ${escapeHtml(p.name)}</h4><small>${escapeHtml(p.category)} · ${escapeHtml(p.time)}</small></div><div class="search-card-head-right">${dotHtml(level)}<small>${escapeHtml(p.status)}</small></div></div><p>${escapeHtml(p.detail)}</p><div class="search-tip"><b>注意事项：</b>${escapeHtml(p.tips)}</div>${pointBookingsSection(p)}<div class="search-actions"><button class="btn primary search-select" data-id="${p.id}">选中并定位</button><button class="btn secondary search-taxi" data-id="${p.id}">打开高德App</button></div></div>`}).join(''):'<div class="section-note">未找到匹配点位。</div>';box.querySelectorAll('.search-select').forEach(b=>b.onclick=()=>{const id=b.dataset.id;if(presetPointIds().includes(id))selectPresetDestination(id,{promote:true,from:'search'});else focusPoint(id)});box.querySelectorAll('.search-taxi').forEach(b=>b.onclick=()=>launchAmap(b.dataset.id))}
function searchPoints(){const q=document.getElementById('searchInput').value.trim().toLowerCase();if(!q){currentSearchIds=[];document.getElementById('searchResults').innerHTML='<div class="section-note">也可以输入关键词检索全部正式景点、交通节点、酒店与服务点。</div>';return}const hits=POINTS.filter(p=>p.category!=='推荐'&&`${p.name}${p.category}${p.detail}${p.status}${p.source}${p.tips}${p.transport}`.toLowerCase().includes(q)).slice(0,12);renderSearchResults(hits)}
function renderRecommendations(){const box=document.getElementById('recommendations');box.innerHTML=RECOMMENDED.map(id=>{const p=pointById(id);return `<article class="recommend-card"><div class="recommend-card-head"><div class="rec-icon">${pointIcon(id)}</div><div class="recommend-card-main"><h3>${escapeHtml(p.name)}</h3><div class="meta">${escapeHtml(p.bestTime)} · ${escapeHtml(p.status)}</div></div><span class="recommend-type">${escapeHtml(p.recType)}</span></div><p><b>推荐理由：</b>${escapeHtml(p.why)}</p><p><b>提醒：</b>${escapeHtml(p.tips)}</p><div class="platform-links">${(p.platformSources||[]).map(x=>`<a class="platform-link" href="${x[1]}" target="_blank" rel="noopener">${escapeHtml(x[0])}</a>`).join('')}<a class="platform-link" href="https://www.xiaohongshu.com/search_result?keyword=${encodeURIComponent(p.name)}" target="_blank" rel="noopener">小红书站内搜</a></div><div class="recommend-actions"><button class="btn primary rec-focus" data-id="${id}">地图定位</button><button class="btn rec-amap" data-id="${id}">打开高德App</button></div></article>`}).join('');box.querySelectorAll('.rec-focus').forEach(b=>b.onclick=()=>focusRecommendation(b.dataset.id));box.querySelectorAll('.rec-amap').forEach(b=>b.onclick=()=>launchAmap(b.dataset.id))}
function focusRecommendation(id){recommendationMode=true;selectedDay=null;routeVisible=false;rebuildMarkers(null);if(routeLayer)routeLayer.clearLayers();setDayRouteCard(null);const p=pointById(id);if(!p)return;if(mapEngine==='amap'&&amapInstance){syncAmapView();const [lat,lng]=wgs84ToGcj02(p.lat,p.lng);amapInstance.setZoomAndCenter(16,[lng,lat]);return}if(map){map.setView([p.lat,p.lng],15);const m=markers.get(id);if(typeof clusters.zoomToShowLayer==='function')clusters.zoomToShowLayer(m,()=>m.openPopup());else m&&m.openPopup()}}
function focusPoint(id){const p=pointById(id);if(!p)return;if(p.category==='推荐'){focusRecommendation(id);return}recommendationMode=false;if(mapEngine==='amap'&&amapInstance){const [lat,lng]=wgs84ToGcj02(p.lat,p.lng);amapInstance.setZoomAndCenter(16,[lng,lat]);return}if(!map)return;rebuildMarkers(selectedDay);map.setView([p.lat,p.lng],15);const m=markers.get(id);if(typeof clusters.zoomToShowLayer==='function')clusters.zoomToShowLayer(m,()=>m.openPopup());else if(m)m.openPopup()}
function refreshLinkedViews(){renderBookingChecklist();renderDays();renderPresetCards();if(currentSearchIds.length)renderSearchResults(currentSearchIds.map(pointById).filter(Boolean));renderRecommendations();syncAmapView()}
function runSelfCheck(){const errors=[],ids=POINTS.map(p=>p.id),set=new Set(ids),icons=Object.values(POINT_ICONS);if(set.size!==ids.length)errors.push('点位ID重复');POINTS.forEach(p=>{if(!Number.isFinite(p.lat)||!Number.isFinite(p.lng)||p.lat<35.7||p.lat>36.4||p.lng<119.9||p.lng>120.9)errors.push(`坐标异常:${p.id}`);if(!p.source)errors.push(`来源缺失:${p.id}`);if(!POINT_ICONS[p.id])errors.push(`图标缺失:${p.id}`)});if(new Set(icons).size!==icons.length)errors.push('存在重复点位图标');SCHEDULES.forEach(d=>d.route.forEach(id=>{if(!set.has(id))errors.push(`路线缺点:${d.date}/${id}`)}));[...REQUIRED,...OPTIONAL,...RECOMMENDED].forEach(id=>{if(!set.has(id))errors.push(`清单点缺失:${id}`)});BOOKINGS.forEach(b=>b.pointIds.forEach(id=>{if(!set.has(id))errors.push(`预约点缺失:${b.id}/${id}`)}));const box=document.getElementById('auditBox');if(errors.length){box.className='alert warn';box.innerHTML='<b>页面自检发现问题：</b>'+errors.map(escapeHtml).join('；')}else{box.className='alert ok';box.innerHTML=`<b>页面自检通过：</b>${POINTS.length}个点位、${SCHEDULES.length}天日程、${BOOKINGS.length}项预约联动、${RECOMMENDED.length}个其他推荐；点位图标全部唯一，预约状态（含放弃）跨面板同步，多底图容灾已启用。`}}
function showMapNotice(msg){const el=document.getElementById('mapNotice');el.textContent=msg;el.classList.add('show')}
function initFallback(){document.getElementById('map').style.display='none';document.getElementById('legend').style.display='none';const f=document.getElementById('offlineFallback');f.style.display='block';document.getElementById('offlineList').innerHTML=[...REQUIRED,...OPTIONAL].map(pointById).filter(Boolean).map(p=>`<div><b>${pointIcon(p.id)} ${escapeHtml(p.name)}</b><br>${escapeHtml(p.time)} · ${escapeHtml(p.status)}</div>`).join('')}
const BASEMAPS={
 osm:{name:'OSM 标准',url:'https://tile.openstreetmap.org/{z}/{x}/{y}.png',maxZoom:19,attribution:'&copy; OpenStreetMap contributors'},
 'carto-light':{name:'CARTO 浅色',url:'https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png',subdomains:'abcd',maxZoom:20,attribution:'&copy; OpenStreetMap contributors &copy; CARTO'},
 'carto-voyager':{name:'CARTO 导航',url:'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png',subdomains:'abcd',maxZoom:20,attribution:'&copy; OpenStreetMap contributors &copy; CARTO'},
 'carto-dark':{name:'CARTO 深色',url:'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',subdomains:'abcd',maxZoom:20,attribution:'&copy; OpenStreetMap contributors &copy; CARTO'},
 opentopo:{name:'OpenTopoMap 地形',url:'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',maxZoom:17,attribution:'Map data &copy; OpenStreetMap contributors, SRTM | Map style &copy; OpenTopoMap'},
 hot:{name:'OSM 人道主义',url:'https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png',maxZoom:19,attribution:'&copy; OpenStreetMap contributors, Tiles style by HOT'}
};
const FALLBACK_ORDER=['osm','carto-light','carto-voyager','hot','opentopo','carto-dark'];
function setBasemapState(text){const el=document.getElementById('basemapState');if(el)el.textContent=text}
function createTileLayer(id){const c=BASEMAPS[id];if(!c)return null;const options={maxZoom:Number.isFinite(c.maxZoom)?c.maxZoom:19,attribution:c.attribution||'',crossOrigin:true};const sd=c.subdomains;if((typeof sd==='string'&&sd.length)||(Array.isArray(sd)&&sd.length))options.subdomains=sd;const layer=L.tileLayer(c.url,options);let errors=0,first=Date.now();layer.on('tileload',()=>{errors=Math.max(0,errors-1);setBasemapState(`${c.name} · 正常`)});layer.on('tileerror',()=>{errors++;basemapFailures[id]=(basemapFailures[id]||0)+1;if(Date.now()-first<12000&&errors>=5)autoSwitchBasemap(id)});return layer}
function autoSwitchBasemap(failedId){
  if(autoFailoverLock||mapEngine!=='leaflet')return;
  autoFailoverLock=true;
  const fallback=()=>{
    const current=FALLBACK_ORDER.indexOf(failedId),candidates=[...FALLBACK_ORDER.slice(Math.max(0,current+1)),...FALLBACK_ORDER.slice(0,Math.max(0,current+1))];
    const next=candidates.find(id=>id!==failedId&&(basemapFailures[id]||0)<10);
    if(next){showMapNotice('高德底图暂不可用，已切换到'+BASEMAPS[next].name);switchLeafletBasemap(next)}
    else showMapNotice('高德及常规底图均加载失败，请检查网络连接。');
  };
  showMapNotice((BASEMAPS[failedId]?.name||failedId)+'加载异常，正在自动切换高德地图');
  switchToAmap({fallbackToLeaflet:false}).catch(fallback).finally(()=>setTimeout(()=>autoFailoverLock=false,2500));
} function switchLeafletBasemap(id){if(!map||!BASEMAPS[id])return;const config=BASEMAPS[id],layerMax=Number.isFinite(config.maxZoom)?config.maxZoom:19;map.setMaxZoom(layerMax);if(map.getZoom()>layerMax)map.setZoom(layerMax);if(activeTileLayer)map.removeLayer(activeTileLayer);activeBasemap=id;activeTileLayer=createTileLayer(id);activeTileLayer.addTo(map);mapEngine='leaflet';document.getElementById('map').classList.remove('leaflet-map-hidden');document.getElementById('amapMap').classList.remove('active');document.getElementById('amapMap').hidden=true;saveJSON(BASEMAP_KEY,{id});document.getElementById('basemapSelect').value=id;setTimeout(()=>map.invalidateSize(),80)}
function promptAmapConfig(){toggleAmapServicePanel(true);showMapNotice('高德JS API与Web API凭证已内置，无需手动配置。');return true} function loadAmapApi(){if(window.AMap)return Promise.resolve(window.AMap);if(amapApiPromise)return amapApiPromise;window._AMapSecurityConfig={securityJsCode:AMAP_SECURITY_CODE};const plugins=['AMap.Scale','AMap.ToolBar','AMap.Geolocation','AMap.AutoComplete','AMap.PlaceSearch','AMap.Geocoder','AMap.Weather','AMap.Driving','AMap.Walking','AMap.Transfer','AMap.MarkerCluster'];amapApiPromise=new Promise((resolve,reject)=>{const done=()=>window.AMapLoader.load({key:AMAP_JS_KEY,version:'2.0',plugins}).then(resolve).catch(reject);if(window.AMapLoader){done();return}const script=document.createElement('script');script.src='https://webapi.amap.com/loader.js';script.onload=done;script.onerror=()=>reject(new Error('高德地图加载器下载失败'));document.head.appendChild(script)}).catch(error=>{amapApiPromise=null;throw error});return amapApiPromise} function clearAmapOverlays(){if(!amapInstance)return;if(amapMarkerCluster){try{amapMarkerCluster.setData([])}catch(e){}try{if(typeof amapMarkerCluster.setMap==='function')amapMarkerCluster.setMap(null)}catch(e){}amapMarkerCluster=null}if(amapInfoWindow)try{amapInfoWindow.close()}catch(e){};[...amapMarkers,...amapOverlays].forEach(item=>{try{amapInstance.remove(item)}catch(e){}});amapMarkers=[];amapOverlays=[];amapClusterPointMap=new Map()} function amapPointPosition(p){const [lat,lng]=wgs84ToGcj02(p.lat,p.lng);return[lng,lat]}
function renderAmapView(){if(!amapInstance||!window.AMap)return;clearAmapOverlays();const ps=visiblePoints(selectedDay),data=ps.map(p=>{const lnglat=amapPointPosition(p);amapClusterPointMap.set(amapMarkerPositionKey(lnglat),p);return{lnglat,weight:['住宿区域','酒店'].includes(p.category)?5:1,id:p.id}});if(data.length)amapMarkerCluster=new AMap.MarkerCluster(amapInstance,data,{gridSize:38,maxZoom:16,averageCenter:true,clusterByZoomChange:true,renderClusterMarker:amapRenderClusterBadge,renderMarker:amapRenderClusterPoint});if(routeVisible){const days=selectedDay?SCHEDULES.filter(d=>d.date===selectedDay):SCHEDULES.slice(1);days.forEach(d=>{const points=routePoints(d),path=points.map(amapPointPosition);if(path.length<2)return;if(!selectedDay){amapOverlays.push(new AMap.Polyline({path,strokeColor:'#fff',strokeWeight:5,strokeOpacity:.65,lineJoin:'round',zIndex:40}),new AMap.Polyline({path,strokeColor:d.color,strokeWeight:3,strokeOpacity:.58,strokeStyle:'dashed',strokeDasharray:[5,8],lineJoin:'round',zIndex:41}));return}amapOverlays.push(new AMap.Polyline({path,strokeColor:'#fff',strokeWeight:11,strokeOpacity:.94,lineCap:'round',lineJoin:'round',zIndex:45}),new AMap.Polyline({path,strokeColor:d.color,strokeWeight:6,strokeOpacity:1,lineCap:'round',lineJoin:'round',zIndex:46}));const order=routeOrderMap(d);order.forEach((nums,id)=>{const p=pointById(id);if(!p)return;const marker=new AMap.Marker({position:amapPointPosition(p),content:`<div class="amap-route-marker">${travelRouteMarkerHtml(d.color,nums.join('/'),p)}</div>`,offset:new AMap.Pixel(-15,-17),zIndex:700,extData:id,title:p.name});marker.on('click',()=>amapOpenPoint(marker.getExtData()));amapOverlays.push(marker)});for(let i=0;i<path.length-1;i++){const a=path[i],b=path[i+1],count=amapDistanceMeters(a,b)>18000?2:1,rotation=Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI;for(let k=1;k<=count;k++){const ratio=count===1?.5:k/(count+1),position=[a[0]+(b[0]-a[0])*ratio,a[1]+(b[1]-a[1])*ratio];amapOverlays.push(new AMap.Marker({position,content:`<div class="amap-direction-marker">${travelDirectionHtml(d.color,rotation)}</div>`,offset:new AMap.Pixel(-14,-14),zIndex:600}))}}})}if(amapOverlays.length)amapInstance.add(amapOverlays);const fit=selectedDay?routePoints(SCHEDULES.find(x=>x.date===selectedDay)):ps;amapFitTravelPoints(fit,selectedDay?15:11)} function syncAmapView(){if(mapEngine==='amap'&&amapInstance)renderAmapView()}
function switchToAmap({fallbackToLeaflet=true}={}){
  if(mapEngine==='amap'&&amapInstance){
    document.getElementById('basemapSelect').value='amap';
    setBasemapState('高德地图 · 实时路况'+(amapTrafficVisible?'已开启':'已关闭'));
    return Promise.resolve(amapInstance)
  }
  setBasemapState('正在加载高德地图…');
  return loadAmapApi().then(()=>{
    mapEngine='amap';
    document.getElementById('map').classList.add('leaflet-map-hidden');
    const container=document.getElementById('amapMap');
    container.hidden=false;
    container.classList.add('active');
    if(!amapInstance){
      amapInstance=new AMap.Map('amapMap',{zoom:12,center:[120.38,36.066],viewMode:'2D',resizeEnable:true,showIndoorMap:false});
      try{amapInstance.addControl(new AMap.Scale())}catch(e){}
      if(innerWidth>800)try{amapInstance.addControl(new AMap.ToolBar({position:{right:'16px',bottom:'88px'}}))}catch(e){}
      amapInstance.on('click',amapHandleMapClick);
      amapInstance.on('moveend',amapScheduleTrafficSummary);
      amapInstance.on('zoomend',amapScheduleTrafficSummary)
    }
    renderAmapView();
    amapSetTrafficVisible(amapTrafficPreference());
    document.getElementById('basemapSelect').value='amap';
    saveJSON(BASEMAP_KEY,{id:'amap'});
    setBasemapState('高德地图 · 实时路况'+(amapTrafficVisible?'已开启':'已关闭'));
    const panel=document.getElementById('amapServicePanel');
    if(panel&&!panel.hidden)setTimeout(()=>amapTrafficAtCenter().catch(()=>{}),650);
    return amapInstance
  }).catch(error=>{
    showMapNotice('高德地图加载失败：'+error.message);
    document.getElementById('basemapSelect').value=activeBasemap;
    if(fallbackToLeaflet)switchLeafletBasemap(activeBasemap&&BASEMAPS[activeBasemap]?activeBasemap:'carto-light');
    throw error
  })
} function switchBasemap(id,{manual=true}={}){if(id==='amap'){switchToAmap();return}switchLeafletBasemap(id);if(manual)showMapNotice(`已切换到${BASEMAPS[id].name}`)}
function initFallback(){document.getElementById('map').style.display='none';document.getElementById('legend').style.display='none';const f=document.getElementById('offlineFallback');f.style.display='block';document.getElementById('offlineList').innerHTML=[...REQUIRED,...OPTIONAL].map(pointById).filter(Boolean).map(p=>`<div><b>${escapeHtml(p.name)}</b><br>${escapeHtml(p.time)} · ${escapeHtml(p.status)}</div>`).join('')}
function amapSetStatus(text,tone=''){const el=document.getElementById('amapAssistantStatus');if(!el)return;el.textContent=text;el.classList.toggle('amap-assistant-status-error',tone==='error');el.classList.toggle('amap-assistant-status-ok',tone==='ok')}
function amapShowPane(name){document.querySelectorAll('[data-amap-tab]').forEach(btn=>btn.classList.toggle('active',btn.dataset.amapTab===name));document.querySelectorAll('[data-amap-pane]').forEach(pane=>{const active=pane.dataset.amapPane===name;pane.classList.toggle('active',active);pane.hidden=!active})}
function amapButtonBusy(button,busy,busyText){if(!button)return;button.disabled=busy;if(busy){button.dataset.originalText=button.textContent;button.textContent=busyText||'处理中…'}else if(button.dataset.originalText){button.textContent=button.dataset.originalText;delete button.dataset.originalText}}
function amapPoiLocation(poi){const value=poi?.location??poi;if(Array.isArray(value))return value.map(Number);if(typeof value==='string')return amapNormalizeLocation(value);if(value&&typeof value.getLng==='function')return[value.getLng(),value.getLat()];if(value&&Number.isFinite(Number(value.lng))&&Number.isFinite(Number(value.lat)))return[Number(value.lng),Number(value.lat)];return null}
function amapLocationText(location){return location?location.map(v=>Number(v).toFixed(6)).join(','):''}
function amapSetInputLocation(id,label,location,poiId=''){const input=document.getElementById(id),loc=amapPoiLocation(location);if(!input||!loc)return;input.value=label||amapLocationText(loc);input.dataset.location=amapLocationText(loc);input.dataset.poiId=poiId||''}
function amapInputLocation(id){const input=document.getElementById(id);return amapNormalizeLocation(input?.dataset.location||'')}
function amapClearInputLocation(id){const input=document.getElementById(id);if(input){delete input.dataset.location;delete input.dataset.poiId}}
function amapEnsureServices(){
  const ready=mapEngine==='amap'&&amapInstance?Promise.resolve(amapInstance):switchToAmap();
  return ready.then(()=>{
    if(amapAssistantReady)return amapInstance;
    amapAutoComplete=new AMap.AutoComplete({city:AMAP_CITY,citylimit:true});
    amapPlaceSearch=new AMap.PlaceSearch({city:AMAP_CITY,citylimit:true,pageSize:12,pageIndex:1,extensions:'all'});
    amapGeocoder=new AMap.Geocoder({city:AMAP_CITY,radius:1200,extensions:'all'});
    amapWeatherService=new AMap.Weather();
    amapGeolocationService=new AMap.Geolocation({enableHighAccuracy:true,timeout:10000,maximumAge:60000,convert:true,showButton:false,showMarker:false,showCircle:false,panToLocation:false,zoomToAccuracy:false});
    amapAssistantReady=true;
    amapSetStatus('高德服务已就绪','ok');
    return amapInstance
  })
} function amapRenderSuggestions(tips){const box=document.getElementById('amapSuggestions');amapSuggestionPois=(tips||[]).filter(t=>t&&t.name).slice(0,8);if(!amapSuggestionPois.length){box.hidden=true;box.innerHTML='';return}box.innerHTML=amapSuggestionPois.map((tip,index)=>`<button type="button" class="amap-suggestion" data-amap-suggestion="${index}"><b>${escapeHtml(tip.name)}</b><small>${escapeHtml([tip.district,tip.address].filter(Boolean).join(' · ')||'青岛')}</small></button>`).join('');box.hidden=false}
function amapRenderSearchResults(pois,title='搜索结果'){const box=document.getElementById('amapSearchResults');amapSearchPois=(pois||[]).filter(p=>amapPoiLocation(p));if(!amapSearchPois.length){box.innerHTML='<div class="amap-empty">没有找到匹配地点，请换一个关键词或扩大搜索范围。</div>';return}box.innerHTML=`<div class="amap-result-meta"><b>${escapeHtml(title)}</b><span>${amapSearchPois.length} 个结果</span></div>`+amapSearchPois.map((poi,index)=>{const distance=poi.distance?amapFormatDistance(poi.distance):'',type=String(poi.type||'').split(';').slice(0,2).join(' · ');return `<article class="amap-result-card"><h4>${escapeHtml(poi.name||'未命名地点')}</h4><small>${escapeHtml([poi.address,poi.pname,poi.cityname,poi.adname].filter(Boolean).join(' · '))}</small><div class="amap-result-meta"><span>${escapeHtml(type)}</span>${distance?`<span>距中心 ${escapeHtml(distance)}</span>`:''}</div><div class="amap-result-actions"><button type="button" data-amap-result-action="view" data-amap-result-index="${index}">地图查看</button><button type="button" class="primary" data-amap-result-action="route" data-amap-result-index="${index}">去这里</button><button type="button" data-amap-result-action="nav" data-amap-result-index="${index}">高德导航</button></div></article>`}).join('')}
