function amapRouteSummary(mode,result,origin,destination){let distance=0,duration=0,cost='';if(mode==='transit'){const plan=result?.plans?.[0];distance=plan?.walking_distance||result?.distance||0;duration=plan?.time||plan?.duration||0;cost=plan?.cost?` · 约¥${plan.cost}`:''}else{const route=result?.routes?.[0];distance=route?.distance||0;duration=route?.time||route?.duration||0;if(mode==='driving'){const taxi=result?.taxi_cost??result?.taxiCost;if(taxi)cost=` · 预估打车¥${taxi}`}}const modeName=mode==='driving'?'驾车 / 打车':mode==='transit'?'公交地铁':'步行',uri=amapRouteUri(origin,destination,mode,document.getElementById('amapRouteTo').value||'终点'),traffic=mode==='driving'?amapDrivingTrafficBreakdown(result):'';document.getElementById('amapRouteSummary').innerHTML=`<b>${escapeHtml(modeName)} · ${escapeHtml(amapFormatDistance(distance))} · ${escapeHtml(amapFormatDuration(duration))}${escapeHtml(cost)}</b>${traffic}<p>${mode==='driving'?'路线按实时路况规划；打车价格为路线结果估算，不代表叫车平台最终价格。':'路线已绘制到高德地图，下方可查看逐步说明。'}</p><p><a href="${uri}" target="_blank" rel="noopener">在高德地图中继续导航</a></p>`} function amapReverseLookup(location){const loc=amapPoiLocation(location);return amapEnsureServices().then(()=>new Promise((resolve,reject)=>amapGeocoder.getAddress(loc,(status,result)=>{if(status==='complete'&&result?.regeocode)resolve(result.regeocode);else reject(new Error('未查询到该位置的地址'))}))) }
