function weatherIcon(text=''){if(/雷/.test(text))return'⛈️';if(/雨/.test(text))return'🌧️';if(/雪/.test(text))return'🌨️';if(/雾|霾/.test(text))return'🌫️';if(/阴/.test(text))return'☁️';if(/云/.test(text))return'⛅';if(/晴/.test(text))return'☀️';return'🌤️'}
