function tripWeatherDetailHtml(date){const record=tripWeatherRecord(date),label=`8月${Number(date.slice(3))}日`;if(!record)return`<div class="day-weather-detail"><div class="day-weather-period"><b>${label} · 尚未进入预报范围</b>高德公开天气接口仅返回当天至第4天的预报，接近出行日期后会自动更新。</div><div class="day-weather-period"><b>当前状态</b>暂无可核验的日程天气，不使用远期预测冒充准确预报。</div><div class="day-weather-note">页面每30分钟刷新一次高德预报缓存。</div></div>`;const day=weatherValue(record,'dayweather','dayWeather'),night=weatherValue(record,'nightweather','nightWeather'),high=weatherValue(record,'daytemp','dayTemp'),low=weatherValue(record,'nighttemp','nightTemp'),dayWind=weatherValue(record,'daywind','dayWind'),nightWind=weatherValue(record,'nightwind','nightWind'),dayPower=weatherValue(record,'daypower','dayPower'),nightPower=weatherValue(record,'nightpower','nightPower');return`<div class="day-weather-detail"><div class="day-weather-period"><b>${weatherIcon(day)} 白天 · ${escapeHtml(day)} · ${escapeHtml(high)}℃</b>${escapeHtml(dayWind)}风 ${escapeHtml(dayPower)}级 · ${weatherRainHint(day)}</div><div class="day-weather-period"><b>${weatherIcon(night)} 夜间 · ${escapeHtml(night)} · ${escapeHtml(low)}℃</b>${escapeHtml(nightWind)}风 ${escapeHtml(nightPower)}级 · ${weatherRainHint(night)}</div><div class="day-weather-note">高德公开接口提供日/夜预报，不提供小时级降雨概率；“有降水可能”依据天气现象字段判断。</div></div>`}
