function applyTripWeather(data){const forecast=data?.forecasts?.[0],casts=forecast?.casts||[];amapTripWeatherByDate={};casts.forEach(cast=>{const date=weatherValue(cast,'date');if(date!=='--')amapTripWeatherByDate[date]=cast});amapTripWeatherReportTime=weatherValue(forecast,'reporttime','reportTime');renderDays();renderLegend(selectedDay||SCHEDULES[1]?.date)}
