function amapSetTrafficVisible(enabled,{announce=false}={}){if(!amapInstance||!window.AMap)return;if(!amapTrafficLayer)amapTrafficLayer=new AMap.TileLayer.Traffic({zIndex:10,autoRefresh:true,interval:60});amapTrafficVisible=Boolean(enabled);try{if(amapTrafficVisible)amapInstance.add(amapTrafficLayer);else amapInstance.remove(amapTrafficLayer)}catch(e){}saveJSON(AMAP_TRAFFIC_PREF_KEY,{enabled:amapTrafficVisible});const outside=document.getElementById('trafficToggleBtn'),inside=document.getElementById('amapTrafficLayerBtn');if(outside){outside.classList.toggle('traffic-active',amapTrafficVisible);outside.textContent=amapTrafficVisible?'路况已开':'实时路况'}if(inside){inside.classList.toggle('traffic-active',amapTrafficVisible);inside.textContent=amapTrafficVisible?'图层：开启':'图层：关闭'}if(announce){amapSetStatus(amapTrafficVisible?'实时路况已开启':'实时路况已关闭','ok');showMapNotice(amapTrafficVisible?'已开启高德实时路况图层':'已关闭高德实时路况图层')}}
function amapTrafficClass(status=''){const value=String(status).toLowerCase();if(/畅通|smooth/.test(value))return'traffic-smooth';if(/缓行|slow/.test(value))return'traffic-slow';if(/拥堵|congested|严重/.test(value))return'traffic-congested';return'traffic-unknown'}
function amapScheduleTrafficSummary(){clearTimeout(amapTrafficDetailTimer);const panel=document.getElementById('amapServicePanel');if(!amapTrafficVisible||!panel||panel.hidden)return;amapTrafficDetailTimer=setTimeout(()=>amapTrafficAtCenter().catch(()=>{}),1100)}
function amapDrivingTrafficBreakdown(result){const route=result?.routes?.[0],totals={smooth:0,slow:0,congested:0,unknown:0};(route?.steps||[]).forEach(step=>(step.tmcs||[]).forEach(tmc=>{const status=String(tmc.status||'unknown').toLowerCase(),distance=Number(tmc.distance)||0;if(/smooth|畅通/.test(status))totals.smooth+=distance;else if(/slow|缓行/.test(status))totals.slow+=distance;else if(/congested|拥堵|严重/.test(status))totals.congested+=distance;else totals.unknown+=distance}));const parts=[];if(totals.smooth)parts.push(`<span class="traffic-smooth">畅通 ${amapFormatDistance(totals.smooth)}</span>`);if(totals.slow)parts.push(`<span class="traffic-slow">缓行 ${amapFormatDistance(totals.slow)}</span>`);if(totals.congested)parts.push(`<span class="traffic-congested">拥堵 ${amapFormatDistance(totals.congested)}</span>`);if(totals.unknown)parts.push(`<span class="traffic-unknown">未知 ${amapFormatDistance(totals.unknown)}</span>`);return parts.length?`<div class="route-traffic-breakdown">${parts.join('')}</div>`:''} function amapNormalizeLocation(value){if(Array.isArray(value))return value.map(Number);const parts=String(value||'').split(',').map(Number);return parts.length===2&&parts.every(Number.isFinite)?parts:null}
function amapCenter(){if(mapEngine==='amap'&&amapInstance){const c=amapInstance.getCenter();return[c.lng,c.lat]}if(map){const c=map.getCenter(),gcj=wgs84ToGcj02(c.lat,c.lng);return[gcj[1],gcj[0]]}return[120.38,36.066]}
function amapSetOutput(title,body){const el=document.getElementById('amapContextOutput')||document.getElementById('amapServiceOutput');if(el)el.innerHTML='<h3>'+escapeHtml(title)+'</h3>'+body;amapShowPane('travel')} function amapValidateResponse(data){if(data&&(data.status==='1'||data.status===1||data.errcode===0))return data;throw new Error(data?.info||data?.infocode||data?.errmsg||'高德服务返回失败')}
function amapJsonp(url){return new Promise((resolve,reject)=>{const callback='__amap_jsonp_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script'),timer=setTimeout(()=>finish(new Error('高德服务请求超时')),12000);function finish(error,data){clearTimeout(timer);delete window[callback];script.remove();error?reject(error):resolve(data)}window[callback]=data=>finish(null,data);url.searchParams.set('callback',callback);script.src=url.toString();script.onerror=()=>finish(new Error('高德服务网络错误'));document.head.appendChild(script)})}
function amapWebRequest(endpoint,params={}){const url=new URL('https://restapi.amap.com'+endpoint);Object.entries({...params,key:AMAP_WEB_KEY,output:'JSON'}).forEach(([key,value])=>{if(value!==undefined&&value!==null&&value!=='')url.searchParams.set(key,String(value))});return fetch(url.toString(),{mode:'cors',cache:'no-store'}).then(response=>{if(!response.ok)throw new Error('HTTP '+response.status);return response.json()}).then(amapValidateResponse).catch(()=>amapJsonp(url).then(amapValidateResponse))}
