function amapMarkSelectedLocation(location,name='选定位置'){amapLastLngLat=amapNormalizeLocation(location);if(!amapLastLngLat||!amapInstance||!window.AMap)return;clearAmapServiceOverlays();const marker=new AMap.Marker({position:amapLastLngLat,title:name,label:{content:escapeHtml(name),direction:'right'}});amapServiceOverlays.push(marker);amapInstance.add(marker);amapInstance.setZoomAndCenter(16,amapLastLngLat)}
function toggleAmapServicePanel(force){const panel=document.getElementById('amapServicePanel'),button=document.getElementById('amapConfigBtn'),open=typeof force==='boolean'?force:panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));document.querySelector('.map-wrap')?.classList.toggle('amap-assistant-open',open);if(open){amapPopulateTripDestinations();amapSetStatus('正在连接高德服务…');amapEnsureServices().then(()=>{if(!amapServiceLoaded){amapServiceLoaded=true;Promise.allSettled([amapWeatherAtCenter(),amapTrafficAtCenter()])}}).catch(error=>amapSetStatus(error.message,'error'))}} function amapRenderPlaces(title,pois){if(!pois?.length){amapSetOutput(title,'<p>没有找到匹配地点。</p>');return}amapSetOutput(title,pois.slice(0,12).map(p=>'<button class="amap-result" data-amap-location="'+escapeHtml(p.location||'')+'" data-amap-name="'+escapeHtml(p.name||'')+'"><b>'+escapeHtml(p.name||'未命名地点')+'</b><small>'+escapeHtml([p.type,p.address,p.distance?amapFormatDistance(p.distance):''].filter(Boolean).join(' · '))+'</small></button>').join(''))}
function amapSearchPlaces(){const input=document.getElementById('amapSearchInput'),keywords=input.value.trim(),button=document.getElementById('amapSearchBtn');if(!keywords){amapSetStatus('请输入地点或关键词','error');input.focus();return Promise.resolve()}document.getElementById('amapSuggestions').hidden=true;amapButtonBusy(button,true,'搜索中…');amapSetStatus('正在搜索“'+keywords+'”…');return amapEnsureServices().then(()=>new Promise((resolve,reject)=>amapPlaceSearch.search(keywords,(status,result)=>status==='complete'?resolve(result):reject(new Error('没有找到匹配地点'))))).then(result=>{amapRenderSearchResults(result?.poiList?.pois||[],'“'+keywords+'”');amapSetStatus('搜索完成','ok')}).catch(error=>{amapRenderSearchResults([]);amapSetStatus(error.message,'error')}).finally(()=>amapButtonBusy(button,false))} function amapInputTips(){const input=document.getElementById('amapSearchInput'),keywords=input.value.trim();clearTimeout(amapSuggestionTimer);if(keywords.length<2){amapRenderSuggestions([]);return}amapSuggestionTimer=setTimeout(()=>amapEnsureServices().then(()=>amapAutoComplete.search(keywords,(status,result)=>{if(status==='complete')amapRenderSuggestions(result?.tips||[]);else amapRenderSuggestions([])})).catch(()=>{}),220)} function amapNearbySearch(keyword,center){const target=amapPoiLocation(center)||amapCurrentLocation||amapCenter();amapShowPane('search');amapSetStatus('正在搜索附近'+keyword+'…');return amapEnsureServices().then(()=>new Promise((resolve,reject)=>amapPlaceSearch.searchNearBy(keyword,target,3000,(status,result)=>status==='complete'?resolve(result):reject(new Error('附近没有找到'+keyword))))).then(result=>{amapRenderSearchResults(result?.poiList?.pois||[],'附近'+keyword);amapSetStatus('周边搜索完成','ok')}).catch(error=>{amapRenderSearchResults([]);amapSetStatus(error.message,'error')})} function amapReverseAtLocation(location=amapContextLocation||amapLastLngLat||amapCenter()){const target=amapPoiLocation(location);amapSetStatus('正在查询地址…');return amapReverseLookup(target).then(regeo=>{amapRenderContext(target,regeo.formattedAddress,regeo);amapSetStatus('地址查询完成','ok')}).catch(error=>amapSetStatus(error.message,'error'))} function amapWeatherAtCenter(){const center=amapCurrentLocation||amapCenter(),box=document.getElementById('amapWeatherCard');box.textContent='正在查询天气…';return amapEnsureServices().then(()=>amapReverseLookup(center)).then(regeo=>{const component=regeo.addressComponent||{},city=component.adcode||component.city||AMAP_CITY;return Promise.all([new Promise((resolve,reject)=>amapWeatherService.getLive(city,(error,data)=>error?reject(error):resolve(data))),new Promise((resolve,reject)=>amapWeatherService.getForecast(city,(error,data)=>error?reject(error):resolve(data))),loadTripWeather(true).catch(()=>null)])}).then(([live,forecast])=>{const casts=forecast?.forecasts||[];box.innerHTML=`<b>${escapeHtml(live?.city||AMAP_CITY)} · ${weatherIcon(live?.weather||'')} ${escapeHtml(live?.weather||'--')} ${escapeHtml(live?.temperature||'--')}℃</b><div>湿度 ${escapeHtml(live?.humidity||'--')}% · ${escapeHtml(live?.windDirection||live?.winddirection||'--')}风 ${escapeHtml(live?.windPower||live?.windpower||'--')}级</div><div>${casts.slice(0,4).map(c=>`${escapeHtml(c.date||c.day||'')}：${escapeHtml(c.dayWeather||c.dayweather||'--')} / ${escapeHtml(c.nightWeather||c.nightweather||'--')} ${escapeHtml(c.nightTemp||c.nighttemp||'--')}–${escapeHtml(c.dayTemp||c.daytemp||'--')}℃`).join('<br>')}</div><small>高德公开天气为当前实况及4日内日/夜预报。</small>`;amapSetStatus('天气已更新','ok')}).catch(error=>{box.textContent='天气查询失败：'+(error.message||error);amapSetStatus('天气查询失败','error');throw error})} function amapTrafficAtCenter(){const center=amapCurrentLocation||amapCenter(),radius=Number(document.getElementById('amapTrafficRadius')?.value||3000),level=Number(document.getElementById('amapTrafficLevel')?.value||5),box=document.getElementById('amapTrafficDetail');if(box)box.innerHTML='<div class="amap-empty">正在查询周边道路态势…</div>';return amapWebRequest('/v3/traffic/status/circle',{location:center.join(','),radius,level,extensions:'all'}).then(data=>{const traffic=data.trafficinfo||{},roads=[...(traffic.roads||[])],rank=status=>/严重|拥堵/.test(status)?0:/缓行/.test(status)?1:/畅通/.test(status)?2:3;roads.sort((a,b)=>rank(String(a.status))-rank(String(b.status)));const content=`<p><b>${escapeHtml(traffic.description||'未返回总体描述')}</b></p><p>中心：${escapeHtml(amapCurrentLocation?amapCurrentLabel:'地图中心')} · 半径 ${radius/1000} km · 道路等级 ${level} · ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</p>${roads.slice(0,12).map(r=>`<div class="traffic-summary-line"><span>${escapeHtml(r.name||'道路')}</span><span class="traffic-status ${amapTrafficClass(r.status)}">${escapeHtml(r.status||'未知')}${r.speed?` · ${escapeHtml(r.speed)} km/h`:''}</span></div>`).join('')||'<div class="amap-empty">该范围内未返回道路明细。</div>'}`;if(box)box.innerHTML=content;amapSetStatus('路况分析已更新','ok');return data}).catch(error=>{if(box)box.innerHTML=`<div class="amap-empty">路况查询失败：${escapeHtml(error.message)}</div>`;amapSetStatus('路况查询失败','error');throw error})} function amapStaticMap(){const center=amapCenter(),url=new URL('https://restapi.amap.com/v3/staticmap');url.searchParams.set('key',AMAP_WEB_KEY);url.searchParams.set('location',center.join(','));url.searchParams.set('zoom','13');url.searchParams.set('size','750*420');url.searchParams.set('scale','2');url.searchParams.set('markers','mid,,A:'+center.join(','));amapSetOutput('高德静态地图','<img class="amap-static-image" alt="高德静态地图" src="'+url.toString()+'"><p><a href="'+url.toString()+'" target="_blank" rel="noopener">在新窗口打开高清静态地图</a></p>')}
function amapIpLocate(){return amapWebRequest('/v3/ip').then(data=>{const values=String(data.rectangle||'').split(/[;,]/).map(Number);if(values.length!==4||!values.every(Number.isFinite))throw new Error('IP定位未返回有效范围');const location=[(values[0]+values[2])/2,(values[1]+values[3])/2],label=(data.province||'')+(data.city||'')+'（IP定位）';amapCurrentLocation=location;amapCurrentLabel=label;amapSetInputLocation('amapRouteFrom',label,location);document.getElementById('amapLocationText').textContent=label;return switchToAmap().then(()=>{amapMarkSelectedLocation(location,label);amapSetStatus('已使用IP定位，精度较低','ok');return location})})} function amapLocate(){const button=document.getElementById('amapLocateBtn');amapButtonBusy(button,true,'定位中…');amapSetStatus('正在获取当前位置…');return amapEnsureServices().then(()=>new Promise((resolve,reject)=>amapGeolocationService.getCurrentPosition((status,result)=>status==='complete'&&result?.position?resolve(result):reject(new Error(result?.message||'浏览器定位失败'))))).then(result=>{const location=amapPoiLocation(result.position);amapCurrentLocation=location;return amapReverseLookup(location).catch(()=>null).then(regeo=>{const label=regeo?.formattedAddress||'当前位置';amapCurrentLabel=label;amapSetInputLocation('amapRouteFrom',label,location);document.getElementById('amapLocationText').textContent=label;amapMarkSelectedLocation(location,'当前位置');amapSetStatus('定位成功','ok');return location})}).catch(()=>amapIpLocate()).catch(error=>amapSetStatus('定位失败：'+error.message,'error')).finally(()=>amapButtonBusy(button,false))} function resolveAmapLocation(text,fallback){const direct=amapNormalizeLocation(String(text||'').trim());if(direct)return Promise.resolve(direct);if(!String(text||'').trim())return fallback?Promise.resolve(fallback):Promise.reject(new Error('地点不能为空'));return amapEnsureServices().then(()=>new Promise((resolve,reject)=>amapGeocoder.getLocation(String(text).trim(),(status,result)=>{const location=amapPoiLocation(result?.geocodes?.[0]);status==='complete'&&location?resolve(location):reject(new Error('无法解析地点：'+text))}))) } function amapCollectPolyline(path){const points=[];(path?.steps||[]).forEach(step=>String(step.polyline||'').split(';').forEach(value=>{const p=amapNormalizeLocation(value);if(p)points.push(p)}));return points}
function amapRouteUri(origin,destination,mode,name){const mapMode=mode==='driving'?'car':mode==='transit'?'bus':'walk';return 'https://uri.amap.com/navigation?from='+encodeURIComponent(origin.join(',')+',起点')+'&to='+encodeURIComponent(destination.join(',')+','+(name||'终点'))+'&mode='+mapMode+'&policy=1&src=travel-plans&coordinate=gaode&callnative=0'}
function amapPlanRoute(){const button=document.getElementById('amapRouteBtn');amapButtonBusy(button,true,'规划中…');amapSetStatus('正在规划路线…');const fallback=amapCurrentLocation||amapCenter();return Promise.all([amapResolveInput('amapRouteFrom',fallback),amapResolveInput('amapRouteTo')]).then(([origin,destination])=>amapEnsureServices().then(()=>({origin,destination}))).then(({origin,destination})=>new Promise((resolve,reject)=>{amapClearRouteService();const options={map:amapInstance,panel:'amapRouteSteps',hideMarkers:false,autoFitView:document.getElementById('amapAutoFitRoute')?.checked!==false,extensions:'all'};if(amapRouteMode==='driving')amapRouteService=new AMap.Driving({...options,policy:AMap.DrivingPolicy?.REAL_TRAFFIC??0,showTraffic:true});else if(amapRouteMode==='transit')amapRouteService=new AMap.Transfer({...options,city:AMAP_CITY,policy:0,nightflag:true});else amapRouteService=new AMap.Walking(options);amapRouteService.search(origin,destination,(status,result)=>{if(status==='complete'){amapRouteStart=origin;amapRouteEnd=destination;amapRouteSummary(amapRouteMode,result,origin,destination);resolve(result)}else reject(new Error(result?.info||'未找到可用路线'))})})).then(result=>{amapSetStatus('路线规划完成','ok');return result}).catch(error=>{document.getElementById('amapRouteSummary').innerHTML='<div class="amap-empty">'+escapeHtml(error.message)+'</div>';amapSetStatus(error.message,'error')}).finally(()=>amapButtonBusy(button,false))} function toggleAmapTraffic(){
  const desired=mapEngine!=='amap'||!amapTrafficVisible;
  const alreadyActive=mapEngine==='amap'&&amapInstance;
  const snapshot=alreadyActive?{center:amapInstance.getCenter(),zoom:amapInstance.getZoom()}:null;
  const ready=alreadyActive?Promise.resolve(amapInstance):switchToAmap();
  return ready.then(()=>{
    amapSetTrafficVisible(desired,{announce:true});
    if(snapshot){
      const center=snapshot.center;
      requestAnimationFrame(()=>{
        if(mapEngine==='amap'&&amapInstance)amapInstance.setZoomAndCenter(snapshot.zoom,[center.lng,center.lat],true)
      })
    }
    if(desired)amapTrafficAtCenter().catch(()=>{})
  }).catch(error=>amapSetStatus(error.message,'error'))
} function bindAmapServiceUI(){document.getElementById('amapConfigBtn').onclick=()=>toggleAmapServicePanel();document.getElementById('amapServiceClose').onclick=()=>toggleAmapServicePanel(false);document.getElementById('trafficToggleBtn').onclick=toggleAmapTraffic;document.getElementById('amapTrafficLayerBtn').onclick=toggleAmapTraffic;document.querySelectorAll('[data-amap-tab]').forEach(button=>button.onclick=()=>amapShowPane(button.dataset.amapTab));document.getElementById('amapSearchBtn').onclick=amapSearchPlaces;document.getElementById('amapSearchInput').oninput=amapInputTips;document.getElementById('amapSearchInput').onkeydown=event=>{if(event.key==='Enter')amapSearchPlaces()};document.getElementById('amapSuggestions').onclick=event=>{const button=event.target.closest('[data-amap-suggestion]');if(!button)return;const tip=amapSuggestionPois[Number(button.dataset.amapSuggestion)];document.getElementById('amapSuggestions').hidden=true;document.getElementById('amapSearchInput').value=tip.name;if(amapPoiLocation(tip)){amapSearchPois=[tip];amapSelectSearchPoi(0,'route')}else amapSearchPlaces()};document.getElementById('amapSearchResults').onclick=event=>{const button=event.target.closest('[data-amap-result-action]');if(button)amapSelectSearchPoi(button.dataset.amapResultIndex,button.dataset.amapResultAction)};document.querySelectorAll('[data-amap-nearby]').forEach(button=>button.onclick=()=>amapNearbySearch(button.dataset.amapNearby));document.getElementById('amapLocateBtn').onclick=amapLocate;document.getElementById('amapUseLocationBtn').onclick=()=>amapCurrentLocation?amapSetInputLocation('amapRouteFrom',amapCurrentLabel,amapCurrentLocation):amapLocate();document.getElementById('amapReturnHotelBtn').onclick=()=>{const p=pointById('hotel-zone'),location=amapPointPosition(p);amapSetInputLocation('amapRouteTo','住宿区：五四广场—浮山所',location);amapShowPane('route')};['amapRouteFrom','amapRouteTo'].forEach(id=>document.getElementById(id).addEventListener('input',()=>amapClearInputLocation(id)));document.getElementById('amapSwapRouteBtn').onclick=()=>{const from=document.getElementById('amapRouteFrom'),to=document.getElementById('amapRouteTo'),value=from.value,location=from.dataset.location||'',poi=from.dataset.poiId||'';from.value=to.value;from.dataset.location=to.dataset.location||'';from.dataset.poiId=to.dataset.poiId||'';to.value=value;to.dataset.location=location;to.dataset.poiId=poi};document.querySelectorAll('[data-amap-route-mode]').forEach(button=>button.onclick=()=>{amapRouteMode=button.dataset.amapRouteMode;document.querySelectorAll('[data-amap-route-mode]').forEach(item=>item.classList.toggle('active',item===button))});document.getElementById('amapPickMapBtn').onclick=()=>{toggleAmapServicePanel(false);showMapNotice('请点击高德地图上的位置，然后选择“设为终点”')};document.getElementById('amapRouteBtn').onclick=amapPlanRoute;document.getElementById('amapWeatherBtn').onclick=amapWeatherAtCenter;document.getElementById('amapReverseBtn').onclick=()=>amapReverseAtLocation();document.getElementById('amapTrafficStatusBtn').onclick=amapTrafficAtCenter;document.getElementById('amapTrafficRadius').onchange=amapTrafficAtCenter;document.getElementById('amapTrafficLevel').onchange=amapTrafficAtCenter;document.getElementById('amapStaticMapBtn').onclick=amapStaticMap;document.getElementById('amapTaxiPickupBtn').onclick=()=>{amapShowPane('search');amapNearbySearch('出租车站')};document.getElementById('amapTaxiRouteBtn').onclick=()=>{amapRouteMode='driving';document.querySelectorAll('[data-amap-route-mode]').forEach(item=>item.classList.toggle('active',item.dataset.amapRouteMode==='driving'));amapShowPane('route');const to=document.getElementById('amapRouteTo');if(to.value.trim())amapPlanRoute();else amapSetStatus('已切换到驾车 / 打车模式，请设置终点','ok')};document.getElementById('amapContextOutput').onclick=event=>{const button=event.target.closest('[data-amap-context]');if(button)amapUseContext(button.dataset.amapContext)};document.getElementById('amapTripViewBtn').onclick=()=>amapTripAction('view');document.getElementById('amapTripRouteBtn').onclick=()=>amapTripAction('route');document.getElementById('amapTripNavigateBtn').onclick=()=>amapTripAction('nav')} function initMap(){
  if(typeof L==='undefined'){initFallback();return}
  map=L.map('map',{zoomControl:true,preferCanvas:true,minZoom:2,maxZoom:20}).setView([36.066,120.38],12);
  const saved=loadJSON(BASEMAP_KEY,{id:'osm'}).id||'osm',initialBasemap=saved==='amap'?'osm':(BASEMAPS[saved]?saved:'osm');
  switchLeafletBasemap(initialBasemap);clusters=markerGroup();routeLayer=L.layerGroup().addTo(map);hotelLayer=L.layerGroup().addTo(map);
  POINTS.forEach(p=>{const m=L.marker([p.lat,p.lng],{icon:iconFor(p),title:p.name}).bindPopup(popup(p),{maxWidth:370});markers.set(p.id,m)});
  rebuildMarkers(null);clusters.addTo(map);L.circle([36.0648,120.3778],{radius:850,color:'#7c3aed',weight:2,fillColor:'#a78bfa',fillOpacity:.14,dashArray:'5 6'}).bindTooltip('推荐住宿核心区：五四广场—浮山所').addTo(hotelLayer);
  map.on('click',e=>{const gcj=wgs84ToGcj02(e.latlng.lat,e.latlng.lng);amapLastLngLat=[gcj[1],gcj[0]]});
  drawRoutes(null);fitPoints(POINTS.filter(p=>p.category!=='行程节点'&&p.category!=='推荐'),11);if(saved==='amap')setTimeout(()=>switchToAmap().catch(()=>{}),150)
} function activateTab(name,silent=false){document.querySelectorAll('.tab-btn').forEach(btn=>{const active=btn.dataset.tab===name;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active))});document.querySelectorAll('.tab-panel').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===name));if(name==='recommend'&&!silent){recommendationMode=true;selectedDay=null;routeVisible=false;rebuildMarkers(null);if(routeLayer)routeLayer.clearLayers();setDayRouteCard(null);if(mapEngine==='amap')syncAmapView();else fitPoints(RECOMMENDED.map(pointById).filter(Boolean),12)}else if(name!=='recommend'&&recommendationMode&&!silent){recommendationMode=false;routeVisible=true;rebuildMarkers(selectedDay);drawRoutes(selectedDay);if(mapEngine==='amap')syncAmapView();else if(!selectedDay)fitPoints(POINTS.filter(p=>p.category!=='推荐'&&p.category!=='行程节点'),11)}}
function bindTabs(){document.querySelectorAll('.tab-btn').forEach(btn=>btn.onclick=()=>activateTab(btn.dataset.tab))}
function setPanelCollapsed(collapsed){const app=document.querySelector('.app'),panel=document.getElementById('panel'),edge=document.getElementById('panelEdgeToggle');app.classList.toggle('panel-collapsed',collapsed);if(innerWidth<=800){panel.classList.toggle('open',!collapsed);document.getElementById('menuBtn').setAttribute('aria-expanded',String(!collapsed))}edge.setAttribute('aria-expanded',String(!collapsed));saveJSON(PANEL_KEY,{collapsed});setTimeout(()=>{if(map)map.invalidateSize();if(amapInstance)amapInstance.resize()},240)}
function bindUI(){
  document.getElementById('showAll').onclick=showAll;document.getElementById('clearRoutes').onclick=clearRoutes;
  document.getElementById('fitHotels').onclick=()=>{recommendationMode=false;rebuildMarkers(null);if(mapEngine==='amap'&&amapInstance)amapInstance.setZoomAndCenter(14,[120.3778,36.0648]);else if(map)map.setView([36.0648,120.3778],14);activateTab('stay')};
  document.getElementById('searchBtn').onclick=searchPoints;document.getElementById('searchInput').oninput=searchPoints;document.getElementById('searchInput').onkeydown=e=>{if(e.key==='Enter')searchPoints()};
  document.getElementById('presetDestination').onchange=e=>selectPresetDestination(e.target.value,{promote:true,from:'dropdown'});document.getElementById('basemapSelect').onchange=e=>switchBasemap(e.target.value);
  document.getElementById('menuBtn').onclick=()=>setPanelCollapsed(document.getElementById('panel').classList.contains('open'));document.getElementById('panelEdgeToggle').onclick=()=>setPanelCollapsed(!document.querySelector('.app').classList.contains('panel-collapsed'));
  document.addEventListener('change',e=>{if(e.target.matches('[data-booking-progress]'))setBookingProgress(e.target.dataset.bookingProgress,e.target.value)});document.addEventListener('click',e=>{const b=e.target.closest('[data-booking-channel]');if(b)openBookingChannel(b.dataset.bookingChannel,Number(b.dataset.channelIndex))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!document.getElementById('amapServicePanel').hidden)toggleAmapServicePanel(false);else setPanelCollapsed(true)}});
  bindTabs();bindAmapServiceUI();const saved=loadJSON(PANEL_KEY,{collapsed:innerWidth<=800});setPanelCollapsed(Boolean(saved.collapsed));window.addEventListener('resize',()=>{if(innerWidth>800)document.getElementById('panel').classList.remove('open');setTimeout(()=>{if(map)map.invalidateSize();if(amapInstance)amapInstance.resize()},80)})
} function bootstrapApp(){try{normalizePresetOrder();renderBookingChecklist();renderDays();renderSources();renderHotels();renderLegend();renderPresetDestinations();renderRecommendations();runSelfCheck();bindUI();initMap()}catch(err){console.error('Travel map startup failed',err);const box=document.getElementById('auditBox');if(box){box.className='alert warn';box.innerHTML='<b>页面初始化失败：</b>'+escapeHtml(err&&err.message?err.message:String(err))}try{if(typeof L==='undefined')initFallback()}catch(_){}}}
